package com.fifotech.task.config;
import com.fifotech.task.domain.*;import com.fifotech.task.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.LocalDate;
@Configuration public class DemoDataInitializer {@Bean CommandLineRunner seedDemoData(UserRepository users,TaskRepository tasks,PasswordEncoder encoder,@Value("${app.seed-demo-data:true}") boolean enabled){return args->{if(!enabled||users.existsByEmailIgnoreCase("admin@demo.com"))return;User admin=users.save(new User("Demo Admin","admin@demo.com",encoder.encode("Admin@123"),Role.ADMIN,null));User manager=users.save(new User("Demo Manager","manager@demo.com",encoder.encode("Manager@123"),Role.MANAGER,null));User employee1=users.save(new User("Employee One","emp1@demo.com",encoder.encode("Emp@123"),Role.EMPLOYEE,manager));User employee2=users.save(new User("Employee Two","emp2@demo.com",encoder.encode("Emp@123"),Role.EMPLOYEE,manager));tasks.save(new TaskItem("Prepare monthly report","Compile the monthly performance report.",Priority.HIGH,LocalDate.now().plusDays(7),employee1,manager));tasks.save(new TaskItem("Review onboarding checklist","Complete the new hire onboarding checklist.",Priority.MEDIUM,LocalDate.now().plusDays(3),employee2,manager));};}}
